"""Vocab.decode goldens for intern-worker's indra tests.

usage: python -I make_vocab_fixtures.py META_JSON OUT_JSON

"vocabs": per meta vocabulary a token list the CI tests decode with: the whole
base vocabulary (it holds the LaTeX commands), and for the group vocabularies
a reduced list (every Hangul jamo and a sample of the rest) that keeps the
jamo flag.  "cases": id sequences over those lists with Vocab.decode's text.
"full_cases": id sequences over the real meta.json vocabularies (run only when
the models are present).  "alpha_first": per base token, whether
token[:1].isalpha(), and "alpha_tail" per token whether token[1:].isalpha()."""
import json, random, sys
from pathlib import Path
from indra_ocr.vocab import Vocab

meta = json.loads(Path(sys.argv[1]).read_text())
rng = random.Random(11)
full = {k: Vocab.from_json(meta[k]) for k in meta if k.startswith("vocab")}

def reduced(v):
    jamo = [c for c in v.chars if 0x1100 <= ord(c[0]) <= 0x11FF or 0x3130 <= ord(c[0]) <= 0x318F]
    rest = [c for c in v.chars if c not in set(jamo)]
    keep = set(jamo) | set(rng.sample(rest, min(300, len(rest)))) | {" "}
    return [c for c in v.chars if c in keep]

vocabs = {"vocab": full["vocab"].chars}
for k in ("vocab_world", "vocab_rtl", "vocab_cjk"):
    vocabs[k] = reduced(full[k])

def gen_ids(v, n_cases):
    chars = v.chars
    n = len(chars)
    cmds = [i + 1 for i, c in enumerate(chars) if len(c) > 1]
    letters = [i + 1 for i, c in enumerate(chars) if c[:1].isalpha()]
    jamo_l = [i + 1 for i, c in enumerate(chars) if 0x1100 <= ord(c[0]) <= 0x1112]
    jamo_v = [i + 1 for i, c in enumerate(chars) if 0x1161 <= ord(c[0]) <= 0x1175]
    jamo_t = [i + 1 for i, c in enumerate(chars) if 0x11A8 <= ord(c[0]) <= 0x11C2]
    out = []
    for _ in range(n_cases):
        ids = []
        for _ in range(rng.randint(0, 14)):
            r = rng.random()
            if cmds and r < 0.25:
                ids.append(rng.choice(cmds))
            elif letters and r < 0.45:
                ids.append(rng.choice(letters))
            elif jamo_l and jamo_v and r < 0.7:
                ids += [rng.choice(jamo_l), rng.choice(jamo_v)] + ([rng.choice(jamo_t)] if jamo_t and rng.random() < 0.5 else [])
            elif r < 0.73:
                ids.append(rng.choice([0, n + 1, n + 50]))  # out of range: dropped
            else:
                ids.append(rng.randint(1, n))
        out.append(ids)
    return out

cases = []
for k, chars in vocabs.items():
    v = Vocab(chars)
    for ids in gen_ids(v, 120 if k == "vocab" else 60):
        cases.append({"vocab": k, "ids": ids, "text": v.decode(ids)})
# Hand-picked: a command before a letter, a digit, a space, a brace, the end.
base = Vocab(vocabs["vocab"])
idx = base.index
for seq in (["\\alpha", "x"], ["\\alpha", "1"], ["\\alpha", " ", "x"], ["\\frac", "\\{"], ["\\alpha"], ["\\alpha", "\\beta", "é"],
            ["\\,", "x"], ["\\{", "x"], ["x", "\\alpha", "́"]):
    if all(s in idx for s in seq):
        ids = [idx[s] for s in seq]
        cases.append({"vocab": "vocab", "ids": ids, "text": base.decode(ids)})
full_cases = []
for k, v in full.items():
    for ids in gen_ids(v, 40):
        full_cases.append({"vocab": k, "ids": ids, "text": v.decode(ids)})
doc = {
    "note": "Generated by indra-tools/make_vocab_fixtures.py from indra-ocr 1.1.2 vocab.py and meta.json a1283c4b.",
    "vocabs": vocabs,
    "flags": {k: {"jamo": Vocab(c).jamo, "has_commands": Vocab(c).has_commands} for k, c in vocabs.items()},
    "alpha_first": "".join("1" if c[:1].isalpha() else "0" for c in vocabs["vocab"]),
    "alpha_tail": "".join("1" if c[1:].isalpha() else "0" for c in vocabs["vocab"]),
    "cases": cases,
    "full_cases": full_cases,
}
Path(sys.argv[2]).write_text(json.dumps(doc, ensure_ascii=False, separators=(",", ":")))
print(len(cases), len(full_cases), Path(sys.argv[2]).stat().st_size, doc["flags"],
      sum(1 for c in cases if "\\" in c["text"] and " " in c["text"]))
